SELECT id,target_type,target_id,reporter_user_id,reason_code,reason_text,status,
       handled_by,handled_at,handling_note,created_at,updated_at
FROM community_report

    AND status=#{status}

ORDER BY created_at ASC, id ASC
LIMIT #{limit} OFFSET #{offset}

